package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.nio.file.*;import java.nio.file.attribute.*;
public class ApprovedCredentialAuthorityTest {
 static String id(int n){return String.format("00000000-0000-4000-8000-%012d",n);}static ApprovedCredentialAuthority.Binding binding(boolean active){return new ApprovedCredentialAuthority.Binding(id(1),id(2),"approved-revision-1","DEEPSEEK","https://api.deepseek.com",id(3),"a".repeat(64),active);}
 @Test void exactDeploymentBindingCannotCrossTenantRevisionOrEndpoint(){var a=new ApprovedCredentialAuthority((t,r)->List.of(binding(true)));var good=a.require(id(1),id(2),"approved-revision-1","DEEPSEEK","https://api.deepseek.com");good.requireCurrent();assertThrows(TenantAccessException.class,()->a.require(id(4),id(2),"approved-revision-1","DEEPSEEK","https://api.deepseek.com"));assertThrows(TenantAccessException.class,()->a.require(id(1),id(2),"other","DEEPSEEK","https://api.deepseek.com"));assertThrows(TenantAccessException.class,()->a.require(id(1),id(2),"approved-revision-1","DEEPSEEK","https://attacker.invalid"));}
 @Test void revokedOrAmbiguousDeploymentReferencesReject(){var rows=new ArrayList<ApprovedCredentialAuthority.Binding>();rows.add(binding(true));var a=new ApprovedCredentialAuthority((t,r)->List.copyOf(rows));var proof=a.require(id(1),id(2),"approved-revision-1","DEEPSEEK","https://api.deepseek.com");rows.set(0,binding(false));assertThrows(TenantAccessException.class,proof::requireCurrent);rows.add(binding(true));assertThrows(TenantAccessException.class,proof::requireCurrent);}
 @Test void realManifestReaderRejectsUnsafeModesDuplicateAndSymlink()throws Exception{var dir=Files.createTempDirectory("approved-reference-fixture-");var file=dir.resolve("references.json");try{Files.setPosixFilePermissions(dir,PosixFilePermissions.fromString("rwx------"));String row="{\"tenant_id\":\""+id(1)+"\",\"reference_id\":\""+id(2)+"\",\"revision\":\"approved-revision-1\",\"provider\":\"DEEPSEEK\",\"endpoint\":\"https://api.deepseek.com\",\"approval_version\":\""+id(3)+"\",\"approval_sha256\":\""+"a".repeat(64)+"\",\"active\":true}";Files.writeString(file,"["+row+"]");Files.setPosixFilePermissions(file,PosixFilePermissions.fromString("rw-------"));var reader=new ConfiguredCredentialDirectory(file);assertEquals(List.of(binding(true)),reader.current(id(1),id(2)));Files.setPosixFilePermissions(file,PosixFilePermissions.fromString("rw-r--r--"));assertThrows(TenantAccessException.class,()->reader.current(id(1),id(2)));Files.setPosixFilePermissions(file,PosixFilePermissions.fromString("rw-------"));Files.writeString(file,"["+row+","+row+"]");assertThrows(TenantAccessException.class,()->reader.current(id(1),id(2)));var link=dir.resolve("link.json");Files.createSymbolicLink(link,file);assertThrows(TenantAccessException.class,()->new ConfiguredCredentialDirectory(link).current(id(1),id(2)));Files.delete(link);}finally{Files.deleteIfExists(file);Files.deleteIfExists(dir);}}
 public static void main(String[]args)throws Exception{var t=new ApprovedCredentialAuthorityTest();t.exactDeploymentBindingCannotCrossTenantRevisionOrEndpoint();t.revokedOrAmbiguousDeploymentReferencesReject();t.realManifestReaderRejectsUnsafeModesDuplicateAndSymlink();System.out.println("PASS 3 credential reference tests; no secret bytes or network used");}
}
